INSERT INTO #iso_prac (control_code, practice_code, practice_name, practice_description, obligation)
VALUES
(N'5.1', N'5.1.1', N'Maintain an approved high-level Information Security Policy.', N'A high-level Information Security Policy is documented, setting the overall goals for the company. Assign an owner, follow the activity consistently, review it when required, and keep suitable evidence.', N'Maintain, approve, and review the main Information Security Policy.'),
(N'5.1', N'5.1.2', N'Define topic-specific policies for key operational areas.', N'Topic-specific policies (e.g., Access Control, Clear Desk, Cloud Security) are defined for operational areas. Assign an owner, follow the activity consistently, review it when required, and keep suitable evidence.', N'Maintain approved topic-specific security policies for key operational areas.'),
(N'5.1', N'5.1.3', N'Obtain formal senior management approval for all policies.', N'All policies are formally approved by senior management (CEO/CISO). Assign an owner, follow the activity consistently, review it when required, and keep suitable evidence.', N'Obtain senior management approval before policies are issued or changed.'),
(N'5.1', N'5.1.4', N'Publish approved policies for employees and relevant contractors.', N'Policies are published and made easily accessible to all employees (and contractors where relevant). Assign an owner, follow the activity consistently, review it when required, and keep suitable evidence.', N'Make approved policies available to employees and relevant contractors.'),
(N'5.1', N'5.1.5', N'Communicate policy changes through a formal process.', N'A formal process is in place to communicate policy changes to the workforce. Assign an owner, follow the activity consistently, review it when required, and keep suitable evidence.', N'Communicate policy changes to relevant employees when policies are updated.'),
(N'5.1', N'5.1.6', N'Review policies annually or after significant changes.', N'Policies are reviewed at least annually or when significant organizational/technical changes occur. Assign an owner, follow the activity consistently, review it when required, and keep suitable evidence.', N'Review policies annually or when major business, legal, or technical changes occur.'),
(N'5.1', N'5.1.7', N'Measure policy effectiveness through checks or audits.', N'The effectiveness of policies is measured (e.g., through compliance checks or audits). Assign an owner, follow the activity consistently, review it when required, and keep suitable evidence.', N'Check policy effectiveness through audits, compliance checks, or reviews.'),
(N'5.1', N'5.1.8', N'Align policies with legal, regulatory, and contractual requirements.', N'Policies are aligned with legal, regulatory, and contractual requirements. Assign an owner, follow the activity consistently, review it when required, and keep suitable evidence.', N'Align policies with legal, regulatory, contractual, and business requirements.'),
(N'5.1', N'5.1.9', N'Assign policy owners and manage approved policy exceptions.', N'Each information security policy should have an owner. Any exception to a policy should be recorded, approved, time-bound, reviewed, and closed when no longer needed.', N'Assign owners for policies and formally approve, review, and close policy exceptions.'),
(N'5.10', N'5.10.1', N'Ensure that a formal "Acceptable Use Policy" (AUP) is documented, covering email, internet, social media, and hardware.', N'A formal "Acceptable Use Policy" (AUP) is documented, covering email, internet, social media, and hardware. Assign an owner, follow the activity consistently, review it when required, and keep suitable evidence.', N'Ensure a formal "Acceptable Use Policy" (AUP) is documented, covering email, internet, social media, and hardware, keep records updated, and review ownership or status regularly.'),
(N'5.10', N'5.10.2', N'Ensure that the AUP specifically prohibits illegal activities, harassment, and actions that jeopardize security.', N'The AUP specifically prohibits illegal activities, harassment, and actions that jeopardize security. Assign an owner, follow the activity consistently, review it when required, and keep suitable evidence.', N'Ensure the AUP specifically prohibits illegal activities, harassment, and actions that jeopardize security, align it with applicable requirements, and keep review evidence.'),
(N'5.10', N'5.10.3', N'Ensure that rules for personal use of company equipment (e.g., "limited personal use allowed") are clearly stated.', N'Rules for personal use of company equipment (e.g., "limited personal use allowed") are clearly stated. Assign an owner, follow the activity consistently, review it when required, and keep suitable evidence.', N'Ensure rules for personal use of company equipment (e.g., "limited personal use allowed") are clearly stated, keep records updated, and review ownership or status regularly.'),
(N'5.10', N'5.10.4', N'Ensure that employees and contractors formally acknowledge the AUP upon hire and during significant updates.', N'Employees and contractors formally acknowledge the AUP upon hire and during significant updates. Assign an owner, follow the activity consistently, review it when required, and keep suitable evidence.', N'Ensure employees and contractors formally acknowledge the AUP upon hire and during significant updates, monitor supplier compliance, and keep contract or review records.'),
(N'5.10', N'5.10.5', N'Ensure users are made aware of the consequences of violating acceptable use rules (link to disciplinary process).', N'Users are made aware of the consequences of violating acceptable use rules (link to disciplinary process). Assign an owner, follow the activity consistently, review it when required, and keep suitable evidence.', N'Ensure users are made aware of the consequences of violating acceptable use rules (link to disciplinary process), assign an owner, follow it consistently, and keep suitable evidence.'),
(N'5.10', N'5.10.6', N'Ensure that periodic awareness campaigns or "refresher" training on acceptable use are conducted.', N'Periodic awareness campaigns or "refresher" training on acceptable use are conducted. Assign an owner, follow the activity consistently, review it when required, and keep suitable evidence.', N'Ensure periodic awareness campaigns or "refresher" training on acceptable use are conducted, communicate it to relevant people, and keep acknowledgement or review evidence.'),
(N'5.10', N'5.10.7', N'Define how information should be stored, processed, transmitted, and disposed of.', N'Define how information should be stored, processed, transmitted, and disposed of. Assign an owner, follow the activity consistently, review it when required, and keep suitable evidence.', N'Define how information should be stored, processed, transmitted, and disposed of, assign an owner, follow it consistently, and keep suitable evidence.'),
(N'5.10', N'5.10.8', N'Permit installation and use of only authorized software.', N'Permit installation and use of only authorized software. Assign an owner, follow the activity consistently, review it when required, and keep suitable evidence.', N'Permit installation and use of only authorized software, keep records updated, and review ownership or status regularly.'),
(N'5.10', N'5.10.9', N'Require users to protect information assets when working remotely or outside organizational premises.', N'Require users to protect information assets when working remotely or outside organizational premises. Assign an owner, follow the activity consistently, review it when required, and keep suitable evidence.', N'Require users to protect information assets when working remotely or outside organizational premises, review access regularly, and remove it when no longer needed.'),
(N'5.10', N'5.10.10', N'Obtain periodic acknowledgement of acceptable use requirements.', N'Employees and relevant contractors should periodically confirm that they understand and agree to acceptable use requirements for information and assets.', N'Collect periodic acceptable use acknowledgements from employees and relevant contractors.'),
(N'5.11', N'5.11.1', N'Ensure that a formal termination or "Exit" procedure is documented, including a checklist for asset return.', N'A formal termination or "Exit" procedure is documented, including a checklist for asset return. Assign an owner, follow the activity consistently, review it when required, and keep suitable evidence.', N'Ensure a formal termination or "Exit" procedure is documented, including a checklist for asset return, keep records updated, and review ownership or status regularly.'),
(N'5.11', N'5.11.2', N'Ensure all physical assets (laptops, keys, ID badges, tokens) are recovered before or on the last day of work.', N'All physical assets (laptops, keys, ID badges, tokens) are recovered before or on the last day of work. Assign an owner, follow the activity consistently, review it when required, and keep suitable evidence.', N'Ensure all physical assets (laptops, keys, ID badges, tokens) are recovered before or on the last day of work, keep records updated, and review ownership or status regularly.'),
(N'5.11', N'5.11.3', N'Ensure that access to digital assets (Cloud accounts, VPNs, Email) is revoked as part of the asset return process.', N'Access to digital assets (Cloud accounts, VPNs, Email) is revoked as part of the asset return process. Assign an owner, follow the activity consistently, review it when required, and keep suitable evidence.', N'Ensure access to digital assets (Cloud accounts, VPNs, Email) is revoked as part of the asset return process, review access regularly, and remove it when no longer needed.'),
(N'5.11', N'5.11.4', N'Ensure that in cases where an employee uses a personal device (BYOD), company data is verified as removed/deleted.', N'In cases where an employee uses a personal device (BYOD), company data is verified as removed/deleted. Assign an owner, follow the activity consistently, review it when required, and keep suitable evidence.', N'Ensure in cases where an employee uses a personal device (BYOD), company data is verified as removed/deleted, keep records updated, and review ownership or status regularly.'),
(N'5.11', N'5.11.5', N'Ensure that knowledge and intellectual property (e.g., passwords, documentation) are transferred back to the company.', N'Knowledge and intellectual property (e.g., passwords, documentation) are transferred back to the company. Assign an owner, follow the activity consistently, review it when required, and keep suitable evidence.', N'Ensure knowledge and intellectual property (e.g., passwords, documentation) are transferred back to the company, review access regularly, and remove it when no longer needed.'),
(N'5.11', N'5.11.6', N'Confirm asset return completion during offboarding.', N'Asset return should be checked before or immediately after employment or contract end, including physical assets, digital assets, and knowledge transfer.', N'Confirm returned assets and access closure during offboarding.'),
(N'5.12', N'5.12.1', N'Ensure that a formal information classification scheme is defined (e.g., Public, Internal, Confidential, Secret).', N'A formal information classification scheme is defined (e.g., Public, Internal, Confidential, Secret). Assign an owner, follow the activity consistently, review it when required, and keep suitable evidence.', N'Ensure a formal information classification scheme is defined (e.g., Public, Internal, Confidential, Secret), align it with applicable requirements, and keep review evidence.'),
(N'5.12', N'5.12.2', N'Ensure that criteria for classifying information are based on business value, legal requirements, and sensitivity.', N'Criteria for classifying information are based on business value, legal requirements, and sensitivity. Assign an owner, follow the activity consistently, review it when required, and keep suitable evidence.', N'Ensure criteria for classifying information are based on business value, legal requirements, and sensitivity, align it with applicable requirements, and keep review evidence.'),
(N'5.12', N'5.12.3', N'Ensure that responsibility for classifying information is assigned to the "Information Owner.".', N'Responsibility for classifying information is assigned to the "Information Owner.". Assign an owner, follow the activity consistently, review it when required, and keep suitable evidence.', N'Ensure responsibility for classifying information is assigned to the "Information Owner.", communicate it to relevant people, and keep acknowledgement or review evidence.'),
(N'5.12', N'5.12.4', N'Ensure that handling procedures (storage, transmission, disposal) are defined for each level of classification.', N'Handling procedures (storage, transmission, disposal) are defined for each level of classification. Assign an owner, follow the activity consistently, review it when required, and keep suitable evidence.', N'Ensure handling procedures (storage, transmission, disposal) are defined for each level of classification, align it with applicable requirements, and keep review evidence.'),
(N'5.12', N'5.12.5', N'Ensure that classification levels are reviewed periodically to ensure they still meet business and legal needs.', N'Classification levels are reviewed periodically to ensure they still meet business and legal needs. Assign an owner, follow the activity consistently, review it when required, and keep suitable evidence.', N'Ensure classification levels are reviewed periodically to ensure they still meet business and legal needs, align it with applicable requirements, and keep review evidence.'),
(N'5.12', N'5.12.6', N'Ensure that the classification scheme is aligned with external requirements (e.g., GDPR, HIPAA, or Client Contracts).', N'The classification scheme is aligned with external requirements (e.g., GDPR, HIPAA, or Client Contracts). Assign an owner, follow the activity consistently, review it when required, and keep suitable evidence.', N'Ensure the classification scheme is aligned with external requirements (e.g., GDPR, HIPAA, or Client Contracts), monitor supplier compliance, and keep contract or review records.'),
(N'5.12', N'5.12.7', N'Ensure that access controls are assigned based on the classification level and the principle of least privilege.', N'Access controls are assigned based on the classification level and the principle of least privilege. Assign an owner, follow the activity consistently, review it when required, and keep suitable evidence.', N'Ensure access controls are assigned based on the classification level and the principle of least privilege, review access regularly, and remove it when no longer needed.'),
(N'5.12', N'5.12.8', N'Provide training and awareness on information classification requirements and their responsibilities to employees, contractors, and relevant stakeholders.', N'Employees, contractors, and relevant stakeholders receive training and awareness on information classification requirements and their responsibilities. Assign an owner, follow the activity consistently, review it when required, and keep suitable evidence.', N'Provide training and awareness on information classification requirements and their responsibilities to employees, contractors, and relevant stakeholders, monitor supplier compliance, and keep contract or review records.'),
(N'5.12', N'5.12.9', N'Ensure exceptions to classification requirements are formally approved, documented, and periodically reviewed.', N'Exceptions to classification requirements are formally approved, documented, and periodically reviewed. Assign an owner, follow the activity consistently, review it when required, and keep suitable evidence.', N'Ensure exceptions to classification requirements are formally approved, documented, and periodically reviewed, align it with applicable requirements, and keep review evidence.'),
(N'5.12', N'5.12.10', N'Require third parties with access to organizational information to comply with the organization''s classification and handling requirements.', N'Third parties with access to organizational information are required to comply with the organization''s classification and handling requirements. Assign an owner, follow the activity consistently, review it when required, and keep suitable evidence.', N'Require third parties with access to organizational information to comply with the organization''s classification and handling requirements, review access regularly, and remove it when no longer needed.'),
(N'5.12', N'5.12.11', N'Review information classification levels and owners.', N'Information classification levels and ownership should be reviewed so information remains protected according to value, sensitivity, and business need.', N'Review classification levels and assigned information owners.'),
(N'5.13', N'5.13.1', N'Ensure that a formal process for labeling information in accordance with the classification scheme is documented.', N'A formal process for labeling information in accordance with the classification scheme is documented. Assign an owner, follow the activity consistently, review it when required, and keep suitable evidence.', N'Ensure a formal process for labeling information in accordance with the classification scheme is documented, align it with applicable requirements, and keep review evidence.'),
(N'5.13', N'5.13.2', N'Label digital information labeled (e.g., in metadata, headers, footers, or file names).', N'Digital information is labeled (e.g., in metadata, headers, footers, or file names). Assign an owner, follow the activity consistently, review it when required, and keep suitable evidence.', N'Label digital information labeled (e.g., in metadata, headers, footers, or file names), align it with applicable requirements, and keep review evidence.'),
(N'5.13', N'5.13.3', N'Label physical information labeled with clear, visible markers.', N'Physical information (paper files, USBs, backup tapes) is labeled with clear, visible markers. Assign an owner, follow the activity consistently, review it when required, and keep suitable evidence.', N'Label physical information labeled with clear, visible markers, align it with applicable requirements, and keep review evidence.'),
(N'5.13', N'5.13.4', N'Ensure that labels are removed or updated when the classification of information changes.', N'The organization ensures that labels are removed or updated when the classification of information changes. Assign an owner, follow the activity consistently, review it when required, and keep suitable evidence.', N'Ensure labels are removed or updated when the classification of information changes, align it with applicable requirements, and keep review evidence.'),
(N'5.13', N'5.13.5', N'Ensure that training is provided to ensure employees and contractors understand how to read and apply labels.', N'Training is provided to ensure employees and contractors understand how to read and apply labels. Assign an owner, follow the activity consistently, review it when required, and keep suitable evidence.', N'Ensure training is provided to ensure employees and contractors understand how to read and apply labels, monitor supplier compliance, and keep contract or review records.'),
(N'5.13', N'5.13.6', N'Ensure labels clearly indicate the classification level and associated handling requirements for information assets.', N'Labels clearly indicate the classification level and associated handling requirements for information assets. Assign an owner, follow the activity consistently, review it when required, and keep suitable evidence.', N'Ensure labels clearly indicate the classification level and associated handling requirements for information assets, keep records updated, and review ownership or status regularly.'),
(N'5.13', N'5.13.7', N'Ensure that information handling controls, such as access restrictions, encryption, retention, and transfer requirements, are applied based on assigned labels.', N'Information handling controls, such as access restrictions, encryption, retention, and transfer requirements, are applied based on assigned labels. Assign an owner, follow the activity consistently, review it when required, and keep suitable evidence.', N'Ensure information handling controls, such as access restrictions, encryption, retention, and transfer requirements, are applied based on assigned labels, review access regularly, and remove it when no longer needed.'),
(N'5.13', N'5.13.8', N'Conduct periodic reviews to verify that information assets are correctly classified and labelled in accordance with organizational requirements.', N'Periodic reviews are conducted to verify that information assets are correctly classified and labelled in accordance with organizational requirements. Assign an owner, follow the activity consistently, review it when required, and keep suitable evidence.', N'Conduct periodic reviews to verify that information assets are correctly classified and labelled in accordance with organizational requirements, keep records updated, and review ownership or status regularly.'),
(N'5.13', N'5.13.9', N'Monitor compliance with information labelling requirements through audits, reviews, or automated control mechanisms.', N'Compliance with information labelling requirements is monitored through audits, reviews, or automated control mechanisms. Assign an owner, follow the activity consistently, review it when required, and keep suitable evidence.', N'Monitor compliance with information labelling requirements through audits, reviews, or automated control mechanisms, monitor results, record actions, and track closure.'),
(N'5.13', N'5.13.10', N'Check correct labelling of sensitive information.', N'Sensitive information should be checked to confirm labels are applied correctly in documents, systems, emails, and physical records.', N'Check that sensitive information is labelled correctly.'),
(N'5.14', N'5.14.1', N'Ensure that formal transfer policies and procedures are in place for all communication facilities (Email, Chat, SFTP).', N'Formal transfer policies and procedures are in place for all communication facilities (Email, Chat, SFTP). Assign an owner, follow the activity consistently, review it when required, and keep suitable evidence.', N'Ensure formal transfer policies and procedures are in place for all communication facilities (Email, Chat, SFTP), assign an owner, follow it consistently, and keep suitable evidence.'),
(N'5.14', N'5.14.2', N'Ensure that transfer agreements (like NDAs or Data Processing Agreements) are signed before sharing sensitive data.', N'Transfer agreements (like NDAs or Data Processing Agreements) are signed before sharing sensitive data. Assign an owner, follow the activity consistently, review it when required, and keep suitable evidence.', N'Ensure transfer agreements (like NDAs or Data Processing Agreements) are signed before sharing sensitive data, assign an owner, follow it consistently, and keep suitable evidence.'),
(N'5.14', N'5.14.3', N'Ensure that electronic messaging (Email/Teams/Slack) is protected from unauthorized access or modification.', N'Electronic messaging (Email/Teams/Slack) is protected from unauthorized access or modification. Assign an owner, follow the activity consistently, review it when required, and keep suitable evidence.', N'Ensure electronic messaging (Email/Teams/Slack) is protected from unauthorized access or modification, review access regularly, and remove it when no longer needed.'),
(N'5.14', N'5.14.4', N'Ensure that rules for the use of online collaboration tools and cloud storage are defined and enforced.', N'Rules for the use of online collaboration tools and cloud storage are defined and enforced. Assign an owner, follow the activity consistently, review it when required, and keep suitable evidence.', N'Ensure rules for the use of online collaboration tools and cloud storage are defined and enforced, monitor supplier compliance, and keep contract or review records.'),
(N'5.14', N'5.14.5', N'Ensure that physical media transfers (USB/Hard drives) use encryption and trackable couriers.', N'Physical media transfers (USB/Hard drives) use encryption and trackable couriers. Assign an owner, follow the activity consistently, review it when required, and keep suitable evidence.', N'Ensure physical media transfers (USB/Hard drives) use encryption and trackable couriers, keep records updated, and review ownership or status regularly.'),
(N'5.14', N'5.14.6', N'Ensure users are trained on the risks of social engineering and "accidental" data leaks during transfer.', N'Users are trained on the risks of social engineering and "accidental" data leaks during transfer. Assign an owner, follow the activity consistently, review it when required, and keep suitable evidence.', N'Ensure users are trained on the risks of social engineering and "accidental" data leaks during transfer, assign an owner, follow it consistently, and keep suitable evidence.'),
(N'5.14', N'5.14.7', N'Ensure that cross-border or regulatory-sensitive information transfers are conducted in accordance with applicable legal, contractual, privacy, and regulatory requirements.', N'Cross-border or regulatory-sensitive information transfers are conducted in accordance with applicable legal, contractual, privacy, and regulatory requirements. Assign an owner, follow the activity consistently, review it when required, and keep suitable evidence.', N'Ensure cross-border or regulatory-sensitive information transfers are conducted in accordance with applicable legal, contractual, privacy, and regulatory requirements, monitor supplier compliance, and keep contract or review records.'),
(N'5.14', N'5.14.8', N'Ensure information shared via removable media is scanned for malware before transfer and upon receipt where applicable.', N'Information shared via removable media is scanned for malware before transfer and upon receipt where applicable. Assign an owner, follow the activity consistently, review it when required, and keep suitable evidence.', N'Ensure information shared via removable media is scanned for malware before transfer and upon receipt where applicable, keep records updated, and review ownership or status regularly.'),
(N'5.14', N'5.14.9', N'Ensure that data Loss Prevention (DLP) or equivalent controls are implemented where appropriate to prevent unauthorized disclosure of sensitive information.', N'Data Loss Prevention (DLP) or equivalent controls are implemented where appropriate to prevent unauthorized disclosure of sensitive information. Assign an owner, follow the activity consistently, review it when required, and keep suitable evidence.', N'Ensure data Loss Prevention (DLP) or equivalent controls are implemented where appropriate to prevent unauthorized disclosure of sensitive information, monitor results, record actions, and track closure.'),
(N'5.14', N'5.14.10', N'Ensure that access rights to information-sharing platforms, cloud storage, and file transfer services are restricted to authorized users.', N'Access rights to information-sharing platforms, cloud storage, and file transfer services are restricted to authorized users. Assign an owner, follow the activity consistently, review it when required, and keep suitable evidence.', N'Ensure access rights to information-sharing platforms, cloud storage, and file transfer services are restricted to authorized users, review access regularly, and remove it when no longer needed.'),
(N'5.14', N'5.14.11', N'Ensure that secure file transfer mechanisms (e.g., SFTP, FTPS, HTTPS, secure managed file transfer solutions) are used for transferring sensitive information.', N'Secure file transfer mechanisms (e.g., SFTP, FTPS, HTTPS, secure managed file transfer solutions) are used for transferring sensitive information. Assign an owner, follow the activity consistently, review it when required, and keep suitable evidence.', N'Ensure secure file transfer mechanisms (e.g., SFTP, FTPS, HTTPS, secure managed file transfer solutions) are used for transferring sensitive information, assign an owner, follow it consistently, and keep suitable evidence.'),
(N'5.14', N'5.14.12', N'Ensure that sensitive or confidential information transferred electronically is protected using approved encryption methods during transmission.', N'Sensitive or confidential information transferred electronically is protected using approved encryption methods during transmission. Assign an owner, follow the activity consistently, review it when required, and keep suitable evidence.', N'Ensure sensitive or confidential information transferred electronically is protected using approved encryption methods during transmission, assign an owner, follow it consistently, and keep suitable evidence.'),
(N'5.14', N'5.14.13', N'Review secure information transfer methods.', N'Information transfer methods should be reviewed to confirm sensitive information is shared only through approved and protected channels.', N'Review approved transfer methods and correct unsafe transfers.'),
(N'5.15', N'5.15.1', N'Ensure that an Access Control Policy is established based on business and security requirements (e.g., "Need to Know").', N'An Access Control Policy is established based on business and security requirements (e.g., "Need to Know"). Assign an owner, follow the activity consistently, review it when required, and keep suitable evidence.', N'Ensure an Access Control Policy is established based on business and security requirements (e.g., "Need to Know"), review access regularly, and remove it when no longer needed.'),
(N'5.15', N'5.15.2', N'Ensure users are only granted access to the specific resources required for their current job role.', N'Users are only granted access to the specific resources required for their current job role. Assign an owner, follow the activity consistently, review it when required, and keep suitable evidence.', N'Ensure users are only granted access to the specific resources required for their current job role, review access regularly, and remove it when no longer needed.'),
(N'5.15', N'5.15.3', N'Ensure that a formal process exists for requesting, approving, and granting access to systems and data.', N'A formal process exists for requesting, approving, and granting access to systems and data. Assign an owner, follow the activity consistently, review it when required, and keep suitable evidence.', N'Ensure a formal process exists for requesting, approving, and granting access to systems and data, review access regularly, and remove it when no longer needed.'),
(N'5.15', N'5.15.4', N'Ensure access rights are reviewed at regular, planned intervals (e.g., quarterly or bi-annually).', N'Access rights are reviewed at regular, planned intervals (e.g., quarterly or bi-annually). Assign an owner, follow the activity consistently, review it when required, and keep suitable evidence.', N'Ensure access rights are reviewed at regular, planned intervals (e.g., quarterly or bi-annually), review access regularly, and remove it when no longer needed.'),
(N'5.15', N'5.15.5', N'Ensure access rights are immediately removed upon termination of employment or contract.', N'Access rights are immediately removed upon termination of employment or contract. Assign an owner, follow the activity consistently, review it when required, and keep suitable evidence.', N'Ensure access rights are immediately removed upon termination of employment or contract, review access regularly, and remove it when no longer needed.'),
(N'5.15', N'5.15.6', N'Ensure access rights are adjusted when a user changes roles within the organization.', N'Access rights are adjusted when a user changes roles within the organization. Assign an owner, follow the activity consistently, review it when required, and keep suitable evidence.', N'Ensure access rights are adjusted when a user changes roles within the organization, review access regularly, and remove it when no longer needed.'),
(N'5.15', N'5.15.7', N'Ensure that privileged access (Admins) is strictly controlled and kept to a minimum number of users.', N'Privileged access (Admins) is strictly controlled and kept to a minimum number of users. Assign an owner, follow the activity consistently, review it when required, and keep suitable evidence.', N'Ensure privileged access (Admins) is strictly controlled and kept to a minimum number of users, review access regularly, and remove it when no longer needed.'),
(N'5.15', N'5.15.8', N'Ensure access rights are assigned based on the principles of least privilege and need-to-know to minimize the risk of unauthorized access.', N'Access rights are assigned based on the principles of least privilege and need-to-know to minimize the risk of unauthorized access. Assign an owner, follow the activity consistently, review it when required, and keep suitable evidence.', N'Ensure access rights are assigned based on the principles of least privilege and need-to-know to minimize the risk of unauthorized access, review access regularly, and remove it when no longer needed.'),
