-- ============================================================================
-- ISO Controls Import to GRAC v1.0
-- Phase 3 -- Insert ISO repository practices (grac_new.requirement) + control<->practice map
-- ============================================================================
-- Fill in the two parameters below before running.
-- @release_id : the grac_new.release row that represents the ISO release
--               these controls belong to. Get it from grac_new.release +
--               artifact + authority.
-- ============================================================================
SET NOCOUNT ON;
SET XACT_ABORT ON;
GO

DECLARE @release_id       BIGINT = /* <FILL_IN> */ NULL;
DECLARE @artifact_id      BIGINT = (SELECT artifact_id FROM grac_new.release WHERE release_id = @release_id);
DECLARE @actor            NVARCHAR(100) = 'iso-import-v1.0';

IF @release_id IS NULL OR @artifact_id IS NULL
BEGIN
    RAISERROR('Set @release_id before running this script.', 16, 1);
    RETURN;
END
GO

DECLARE @release_id BIGINT = /* <FILL_IN> */ NULL;
DECLARE @actor      NVARCHAR(100) = 'iso-import-v1.0';
IF @release_id IS NULL BEGIN RAISERROR('Set @release_id.', 16, 1); RETURN; END;

-- Staging: one row per practice from the Excel.
-- practice_code is derived as {control_code}.{seq} in Excel row order per control.
-- Extra Excel columns (assurance frequency, obligation frequency, assurance
-- subject/type/location, evidence, control statement) are per-practice-instance
-- attributes and are captured when a Practice becomes a Practice Instance at
-- the organization tier. They are NOT persisted at the grac_new.requirement
-- level in the current schema.
IF OBJECT_ID('tempdb..#iso_prac') IS NOT NULL DROP TABLE #iso_prac;
CREATE TABLE #iso_prac (
    control_code          NVARCHAR(60)  NOT NULL,
    practice_code         NVARCHAR(60)  NOT NULL,
    practice_name         NVARCHAR(500) NOT NULL,
    practice_description  NVARCHAR(MAX) NULL,
    obligation            NVARCHAR(MAX) NULL
);



BEGIN TRAN;

-- 3a. INSERT requirements (skip codes already active so re-runs are safe).
SELECT s.practice_code, s.practice_name, s.practice_description, s.obligation, N'Active', @actor, SYSUTCDATETIME()
FROM #iso_prac s
WHERE NOT EXISTS (
    SELECT 1 FROM grac_new.requirement r WHERE r.requirement_code = s.practice_code AND r.status = N'Active'
);

-- 3b. INSERT control_requirement_map linking each practice to its parent control.
SELECT c.control_id, r.requirement_id, N'Active', @actor, SYSUTCDATETIME()
FROM #iso_prac s
JOIN grac_new.control     c ON c.control_code    = s.control_code   AND c.status = N'Active'
JOIN grac_new.requirement r ON r.requirement_code = s.practice_code AND r.status = N'Active'
WHERE NOT EXISTS (
    SELECT 1 FROM grac_new.control_requirement_map m
    WHERE m.control_id = c.control_id AND m.requirement_id = r.requirement_id
);

COMMIT;

SELECT 'Phase 3 practices loaded' AS Result,
       (SELECT COUNT(*) FROM #iso_prac) AS ExcelPractices,
       (SELECT COUNT(*) FROM grac_new.requirement r
        JOIN grac_new.control_requirement_map m ON m.requirement_id = r.requirement_id
        JOIN grac_new.control c ON c.control_id = m.control_id
        JOIN grac_new.source_control_map scm ON scm.control_id = c.control_id AND scm.release_id = @release_id
        WHERE r.status = N'Active') AS RequirementsMappedForRelease;
GO
